#include <condition_variable>
#include <chrono>
#include <deque>
#include <mutex>
#include <optional>
#include <thread>

class Mailbox {
public:
    void put(int v);       // store + notify_one
    int take();            // wait until present, then remove & return
    bool empty() const;
private:
    mutable std::mutex m_;
    std::condition_variable cv_;
    std::deque<int> q_;
};

tests.code:
Mailbox box;
std::thread t([&box] { std::this_thread::sleep_for(std::chrono::milliseconds(20)); box.put(7); });
CHECK_EQ(box.take(), 7);
t.join();

Mailbox box;
box.put(1);
box.put(2);
CHECK_EQ(box.take(), 1);
CHECK_EQ(box.take(), 2);
